import glob, re

def parse_yaml(content):
    d = {}
    stack = [(d, -1)]
    for line in content.splitlines():
        if not line.strip() or line.strip().startswith('#'):
            continue
        indent = len(line) - len(line.lstrip())
        line_clean = line.split('#')[0].strip()
        if ':' not in line_clean:
            continue
        key, val = line_clean.split(':', 1)
        key = key.strip()
        val = val.strip()
        while stack and indent <= stack[-1][1]:
            stack.pop()
        current_dict = stack[-1][0]
        if val == '':
            new_dict = {}
            current_dict[key] = new_dict
            stack.append((new_dict, indent))
        else:
            # parse val
            if val.startswith('[') and val.endswith(']'):
                parsed_val = [x.strip() for x in val[1:-1].split(',') if x.strip()]
            elif val.lower() == 'true':
                parsed_val = True
            elif val.lower() == 'false':
                parsed_val = False
            else:
                try:
                    if '.' in val:
                        parsed_val = float(val)
                    else:
                        parsed_val = int(val)
                except ValueError:
                    if (val.startswith('\"') and val.endswith('\"')) or (val.startswith(\"'\") and val.endswith(\"'\")):
                        parsed_val = val[1:-1]
                    else:
                        parsed_val = val
            current_dict[key] = parsed_val
    return d

uniform_keys = [
    'service.port', 'service.request_timeout_ms', 'service.max_body_kb',
    'database.pool_size', 'database.statement_timeout_ms', 'database.ssl_mode',
    'cache.ttl_s', 'cache.max_entries', 'auth.issuer', 'auth.token_ttl_s',
    'auth.allow_anonymous', 'tls.verify', 'tls.min_version', 'logging.format',
    'logging.sample_rate', 'features.new_checkout', 'features.async_refunds',
    'features.rate_limiting', 'payments.provider', 'payments.retry_limit',
    'payments.backoff_ms', 'payments.idempotency', 'database.port',
    'auth.required_scopes', 'service.name'
]

files = glob.glob('config/*.yaml')
data = {}
for f in files:
    env = f.split('/')[-1].replace('.yaml', '')
    with open(f) as fd:
        data[env] = parse_yaml(fd.read())

def get_val(d, path):
    parts = path.split('.')
    cur = d
    for p in parts:
        if isinstance(cur, dict) and p in cur:
            cur = cur[p]
        else:
            return None
    return cur

for k in uniform_keys:
    vals = {}
    for env, d in data.items():
        vals[env] = get_val(d, k)
    print(k, vals)
"
